// Node.js with Express
app.get('/projects/:id', async (req, res) => {
  const project = await service.find(req.params.id);
  if (!project) return res.status(404).json({ title: 'Project not found', status: 404 });
  res.set('Cache-Control', 'max-age=60').status(200).json(project);
});
